from typing import List
from pydantic import BaseModel, Field

class EvaluationQuery(BaseModel):
    query_id: str
    query: str
    query_type: str
    target_documents: List[str]
    target_sections: List[str]
    ground_truth_keywords: List[str]
    reference_answer: str
EVALUATION_BENCHMARK_DATASET: List[EvaluationQuery] = [EvaluationQuery(query_id='q1', query="How does speculative decoding achieve inference speedups without modifying the target model's output distribution?", query_type='factual', target_documents=['Fast Inference from Transformers via Speculative Decoding'], target_sections=['Methodology & Algorithm'], ground_truth_keywords=['draft model', 'rejection sampling', 'target model', 'parallel forward pass'], reference_answer='Speculative decoding uses a smaller auxiliary draft model to propose tokens, which are verified in parallel by the target model using modified rejection sampling ensuring identical output distribution.'), EvaluationQuery(query_id='q2', query='Compare the architecture of Medusa decoding with standard speculative decoding.', query_type='comparative', target_documents=['Fast Inference from Transformers via Speculative Decoding', 'Medusa: Simple LLM Inference Acceleration with Multiple Decoding Heads'], target_sections=['Architecture & Approach', 'Methodology & Algorithm'], ground_truth_keywords=['decoding heads', 'draft model', 'tree-based attention', 'VRAM', 'frozen backbone'], reference_answer='Speculative decoding relies on a separate draft model requiring extra VRAM and synchronization, while Medusa attaches multiple lightweight heads directly to the frozen backbone LLM and uses tree attention.'), EvaluationQuery(query_id='q3', query='What is the computational and memory complexity of FlashAttention compared to standard attention?', query_type='factual', target_documents=['FlashAttention: Fast and Memory-Efficient Exact Attention with IO-Awareness'], target_sections=['Algorithm & IO-Aware Tiling', 'Results & Benchmarks'], ground_truth_keywords=['O(N)', 'O(N^2)', 'SRAM', 'HBM', 'tiling', 'online softmax'], reference_answer='FlashAttention achieves linear O(N) memory complexity using IO-aware tiling and online softmax in SRAM, avoiding materializing the quadratic O(N^2) intermediate attention matrix in HBM.'), EvaluationQuery(query_id='q4', query='How does the H2O policy decide which KV-cache tokens to evict during long-context generation?', query_type='factual', target_documents=['H2O: Heavy Hitter Oracle for Efficient Generative Inference of Large Language Models'], target_sections=['Approach: Heavy Hitter Eviction Policy'], ground_truth_keywords=['heavy hitter', 'cumulative attention', 'recent local tokens', 'budget'], reference_answer='H2O tracks the cumulative attention assigned to each token and dynamically retains the top heavy hitter tokens plus recent local window tokens, permanently evicting the rest.'), EvaluationQuery(query_id='q5', query='Which techniques are complementary when optimizing LLM inference latency across memory bandwidth, attention computation, and KV cache?', query_type='multi-hop', target_documents=['Fast Inference from Transformers via Speculative Decoding', 'Medusa: Simple LLM Inference Acceleration with Multiple Decoding Heads', 'FlashAttention: Fast and Memory-Efficient Exact Attention with IO-Awareness', 'H2O: Heavy Hitter Oracle for Efficient Generative Inference of Large Language Models'], target_sections=['Introduction', 'Results & Benchmarks'], ground_truth_keywords=['FlashAttention', 'Speculative', 'Medusa', 'H2O', 'KV cache', 'IO-aware'], reference_answer='FlashAttention optimizes IO-bound attention compute, H2O bounds KV-cache growth for long sequences, and Speculative Decoding/Medusa accelerate memory-bandwidth-bound autoregressive token generation.'), EvaluationQuery(query_id='q6', query='What are the main limitations of speculative decoding under high batch size or compute-bound workloads?', query_type='analytical', target_documents=['Fast Inference from Transformers via Speculative Decoding'], target_sections=['Limitations & Trade-offs'], ground_truth_keywords=['compute-bound', 'high batch-size', 'memory bandwidth', 'diminishes'], reference_answer='Under high batch sizes where GPUs become compute-bound rather than memory-bandwidth-bound, the relative speedup of speculative decoding diminishes while maintaining memory overhead for two models.'), EvaluationQuery(query_id='q7', query='Explain how FlashAttention avoids saving intermediate attention matrices during the forward pass.', query_type='factual', target_documents=['FlashAttention: Fast and Memory-Efficient Exact Attention with IO-Awareness'], target_sections=['Algorithm & IO-Aware Tiling'], ground_truth_keywords=['recomputation', 'backward pass', 'SRAM', 'online softmax'], reference_answer='FlashAttention recomputes intermediate attention blocks on-the-fly in fast SRAM during the backward pass rather than writing and reading large attention matrices to slow HBM.'), EvaluationQuery(query_id='q8', query='What parameter overhead does Medusa introduce relative to the base LLM?', query_type='factual', target_documents=['Medusa: Simple LLM Inference Acceleration with Multiple Decoding Heads'], target_sections=['Architecture & Approach'], ground_truth_keywords=['under 2%', 'lightweight heads', 'frozen'], reference_answer='Medusa introduces under 2% parameter overhead by freezing the base model and training only the lightweight decoding heads.')]
